Sure, I'd be happy to help you with that! Here's a Python program that uses the OpenWeatherMap API to display the current weather and forecast for a given location. Make sure to install the `requests` library if you haven't already by running `pip install requests`.

```python
import requests

def get_weather_data(location):
    """
    Retrieves weather data for the given location using the OpenWeatherMap API.

    :param location: The name of the city or zip code.
    :return: A dictionary containing current and forecast weather data.
    """
    url = f"http://api.openweathermap.org/data/2.5/weather?q={location}&appid=YOUR_API_KEY&units=metric"
    response = requests.get(url)

    if response.status_code == 200:
        data = response.json()
        return {
            "current": {
                "temperature": data["main"]["temp"],
                "description": data["weather"][0]["description"],
                "icon": data["weather"][0]["icon"]
            },
            "forecast": [
                {
                    "time": "12:00",
                    "temperature": data["list"][i]["main"]["temp"],
                    "description": data["list"][i]["weather"][0]["description"],
                    "icon": data["list"][i]["weather"][0]["icon"]
                } for i in range(1, 8)
            ]
        }
    else:
        print(f"Error {response.status_code}: Unable to fetch weather data.")
        return {}


if __name__ == "__main__":
    location = input("Location: ")
    weather_data = get_weather_data(location)

    if weather_data:
        current_weather = weather_data["current"]
        forecast = weather_data["forecast"]

        print(f"Current weather: {current_weather['description']}, Temperature: {current_weather['temperature']}°C")
        print(f"Forecast:")
        for item in forecast:
            print(f"{item['time']}: {item['description']}, Temperature: {item['temperature']}°C")
    else:
        print("No weather data found for the given location.")
```

Replace `YOUR_API_KEY` with your actual OpenWeatherMap API key. You can sign up for a free API key on the OpenWeatherMap website.
